\section{Proofs}
\label{app:proofs}

\begin{proposition}[$\alpha_{\mathrm{eff}}$ monotonicity]
\label{prop:monotone}
$\alpha_{\mathrm{eff}}(b)$ is non-decreasing in $b$, and strictly increasing whenever the batch contains at least one sample with $q_i \in (0,1)$ and $r_i$ is not constant.
\end{proposition}

\begin{proof}[Proof of Proposition~\ref{prop:monotone}]
Let $w_i(b) = (1 - q_i)^b$, $W(b) = \sum_{j=1}^B w_j(b)$, and $\pi_i(b) = w_i(b) / W(b)$.
Then
\begin{equation*}
  \alpha_{\mathrm{eff}}(b) = \sum_{i=1}^{B} \pi_i(b)\, r_i,
\end{equation*}
where $r_i \in \{0, 1\}$ indicates whether sample $i$ is real.
Taking the derivative with respect to $b$:
\begin{align*}
  \frac{d\pi_i}{db}
  &= \pi_i \!\left(\frac{d \ln w_i}{db} - \frac{d \ln W}{db}\right)
  = \pi_i \!\left(\ln(1{-}q_i) - \sum_j \pi_j \ln(1{-}q_j)\right).
\end{align*}
Substituting,
\begin{align*}
  \frac{d\alpha_{\mathrm{eff}}}{db}
  &= \sum_i r_i\, \pi_i \!\left(\ln(1{-}q_i) - \mathbb{E}_{\pi}[\ln(1{-}q)]\right) \\
  &= \mathrm{Cov}_{\pi}\!\bigl(r_i,\, \ln(1{-}q_i)\bigr).
\end{align*}
Since $r_i = \mathbf{1}[q_i \leq 0.5]$, the indicator $r_i$ and $\ln(1{-}q_i)$ are positively associated by construction, so the covariance is non-negative.
\end{proof}

\begin{proposition}[ESS monotonicity]
\label{prop:ess_mono}
$\mathrm{ESS}(b)$ is non-increasing in $b$, and strictly decreasing whenever the batch contains at least two samples with distinct $q$-values.
\end{proposition}

\begin{proof}
Write $\mathrm{ESS}(b) = 1 / \sum_i \pi_i(b)^2$, where $\pi_i(b) = w_i(b) / W(b)$.
The denominator $\sum_i \pi_i^2$ is the Herfindahl index $H$.
Differentiating $H$ with respect to $b$:
\begin{equation*}
  \frac{dH}{db} = 2 \sum_i \pi_i^2 \bigl(\ln(1{-}q_i) - \mathbb{E}_{\pi}[\ln(1{-}q)]\bigr).
\end{equation*}
This equals $2\,\mathrm{Var}_{\pi^2}[\ln(1{-}q)]$ under the $\pi^2$-weighted measure.
Since variance is non-negative and strictly positive when not all $\ln(1{-}q_i)$ coincide (i.e., when at least two $q$-values differ), $H$ is non-decreasing and $\mathrm{ESS} = 1/H$ is non-increasing.
This is a standard property of exponential tilting~\citep{kish1965survey,owen2013mc}.
\end{proof}

\section{Grid Search Details}
\label{app:grid}

Table~\ref{tab:grid_full} reports held-out PPL for all grid-$b$ values at $\rho = 0.4$ (seed\,42).

\begin{table}[h]
\centering
\small
\begin{tabular}{@{}cc@{}}
\toprule
$b$ & PPL $\downarrow$ \\
\midrule
0.1 & 17.657 \\
0.2 & 17.640 \\
0.3 & \textbf{17.640} \\
0.5 & 17.651 \\
1.0 & 17.692 \\
1.5 & 17.718 \\
2.0 & 17.741 \\
3.0 & 17.774 \\
5.0 & 17.818 \\
\bottomrule
\end{tabular}
\caption{Full grid search results ($\rho{=}0.4$, seed\,42).
$b \in [0.1, 0.5]$ forms a broad plateau (three-seed mean for $b{=}0.1$: $17.655 \pm 0.009$); $b{=}0.3$ is the post-hoc best.}
\label{tab:grid_full}
\end{table}

\section{Quality Threshold Sweep}
\label{app:tau_sweep}

\begin{table}[h]
\centering
\small
\begin{tabular}{@{}cccc@{}}
\toprule
$\tau$ & PPL $\downarrow$ & $\Delta$ vs.\ Uniform & Mean $\bstar$ \\
\midrule
0.50 & 17.688 & $-$0.006 & 0.39 \\
0.60 & 17.681 & $-$0.013 & 0.59 \\
0.70 & 17.679 & $-$0.015 & 0.89 \\
\textbf{0.80} & \textbf{17.653} & $\boldsymbol{-}$\textbf{0.041} & \textbf{1.40} \\
0.90 & 17.712 & $+$0.018 & 2.36 \\
0.95 & 17.723 & $+$0.029 & 3.08 \\
\bottomrule
\end{tabular}
\caption{Quality threshold sweep (seed\,42, $\nmin{=}2$, $\rho{=}0.4$).
$\Delta$ relative to uniform baseline (PPL\,=\,17.694).
Values in $\tau \in [0.5, 0.8]$ all improve over uniform; $\tau{=}0.8$ is the recommended default.}
\label{tab:tau}
\end{table}

\section{Constraint Regime Decomposition}
\label{app:regime}

Figure~\ref{fig:regime_decomp} visualizes the constraint regime decomposition over training steps.

\begin{figure}[h]
\centering
\includegraphics[width=\columnwidth]{constraint_regime_decomposition}
\caption{Constraint regime decomposition over training steps ($\rho{=}0.4$, seed\,42).
ESS-binding (blue) dominates throughout (${\sim}$61\%), while $\aeff$-binding (orange) grows from ${\sim}$10\% early to ${\sim}$37\% after step 2{,}000.
Clean batches ($\bstar{=}0$) constitute only ${\sim}$2\%.}
\label{fig:regime_decomp}
\end{figure}

\section{\texorpdfstring{$\tau$--$\rho$}{tau-rho} Rank Preservation}
\label{app:tau_rho}

Figure~\ref{fig:tau_rho_rank} shows the $\tau$--PPL relationship at two contamination levels.

\begin{figure}[h]
\centering
\includegraphics[width=\columnwidth]{tau_rho_rank_preservation}
\caption{PPL as a function of $\tau$ at $\rho \in \{0.4, 0.6\}$.
Optimal $\tau$ shifts from 0.8 ($\rho{=}0.4$) to 0.7 ($\rho{=}0.6$), but $\tau \in [0.7, 0.8]$ performs well across both levels.}
\label{fig:tau_rho_rank}
\end{figure}

\section{Hybrid and Threshold Comparison}
\label{app:hybrid}

Table~\ref{tab:hybrid} compares method families across contamination levels.
Table~\ref{tab:dr_threshold} shows D\&R sensitivity to the detection threshold at both full training length and epoch-matched settings.
Raw PPL traces a U-shaped curve with a minimum at $q{>}0.3$ (17.250, 3 seeds), but this curve conflates filtering quality with multi-epoch exposure: aggressive thresholds retain less data and repeat it more often.
Epoch-matched comparisons (rightmost column of Table~\ref{tab:dr_threshold}) remove the multi-epoch confound: the U-shape vanishes and PPL decreases monotonically, saturating near the adaptive $\bstar$ level at $q{\geq}0.5$.
Figure~\ref{fig:dr_dual_curve} visualizes the two curves.

\begin{table}[h]
\centering
\small
\begin{tabular}{@{}lcc@{}}
\toprule
\textbf{Method} & $\rho{=}0.4$ & $\rho{=}0.6$ \\
\midrule
Uniform & 17.694 & 17.766 \\
Adaptive $\bstar$ & 17.653 & 17.740 \\
Hybrid ($q{>}0.95$ + adaptive) & 17.514 & 17.530$^*$ \\
Detect \& Remove ($q{>}0.5$) & 17.290 & -- \\
Detect \& Remove ($q{>}0.3$) & 17.250 & -- \\
\bottomrule
\end{tabular}
\caption{Method comparison across contamination levels (seed\,42).
$^*$Hybrid at $\rho{=}0.6$ filters high-confidence synthetic ($q{>}0.95$), reducing effective $\rho$ to ${\approx}0.4$; PPL is not directly comparable to $\rho{=}0.6$ baselines.}
\label{tab:hybrid}
\end{table}

\begin{table}[h]
\centering
\small
\setlength{\tabcolsep}{3pt}
\begin{tabular}{@{}ccccc@{}}
\toprule
\textbf{Thresh.} & \textbf{Ret.\ \%} & \textbf{Epochs} & \textbf{Raw PPL} $\downarrow$ & \textbf{Ep.-matched} $\downarrow$ \\
\midrule
$q > 0.1$ & 15.0\% & ${\sim}$6.6 & 17.40 & 18.04 \\
$q > 0.2$ & ${\sim}$23\% & ${\sim}$4.3 & 17.27 & -- \\
$q > 0.3$ & 31.5\% & ${\sim}$3.2 & \textbf{17.250}$^\dagger$ & 17.74 \\
$q > 0.4$ & ${\sim}$38\% & ${\sim}$2.6 & 17.263 & -- \\
$q > 0.5$ & 41.4\% & ${\sim}$2.4 & 17.28 & 17.65 \\
$q > 0.6$ & ${\sim}$46\% & ${\sim}$2.2 & 17.30 & -- \\
$q > 0.7$ & 49.8\% & ${\sim}$2.0 & 17.32 & 17.62 \\
$q > 0.8$ & ${\sim}$56\% & ${\sim}$1.8 & 17.34 & -- \\
$q > 0.9$ & 61.6\% & ${\sim}$1.6 & 17.42 & 17.628 \\
\bottomrule
\end{tabular}
\caption{D\&R threshold sensitivity ($\rho{=}0.4$, seed\,42 unless noted).
Raw PPL traces a U-shaped curve (minimum at $q{>}0.3$); epoch-matched PPL (single content epoch) decreases monotonically and saturates near the adaptive $\bstar$ level (${\approx}$17.65) at $q{\geq}0.5$, confirming the U-shape is a multi-epoch artifact.
$^\dagger$\,3-seed mean $17.250 \pm 0.001$.}
\label{tab:dr_threshold}
\end{table}

\begin{figure}[h]
\centering
\includegraphics[width=\columnwidth]{dr_dual_curve}
\caption{D\&R perplexity as a function of data retained.
\textbf{Blue}: raw (multi-epoch) PPL traces a U-shaped curve; annotations show effective epoch count.
\textbf{Orange}: epoch-matched (single content epoch) PPL decreases monotonically and saturates at $q{\geq}0.5$, matching the adaptive $\bstar$ level (green).
The raw U-shape is entirely a multi-epoch artifact: controlling for data exposure eliminates it.}
\label{fig:dr_dual_curve}
\end{figure}

\section{Downstream Task Evaluation}
\label{app:downstream}

Table~\ref{tab:downstream} reports downstream benchmark accuracy for adaptive vs.\ uniform training at $\rho{=}0.4$ (seed\,42, Qwen3-0.6B).
All differences fall within standard error, confirming that the PPL improvement does not come at the cost of downstream task performance.

\begin{table}[h]
\centering
\small
\begin{tabular}{@{}llccc@{}}
\toprule
\textbf{Benchmark} & \textbf{Metric} & \textbf{Adaptive} & \textbf{Uniform} & $\boldsymbol{\Delta}$ \\
\midrule
ARC-Challenge & acc\_norm & 0.343 & 0.348 & $-$0.005 \\
ARC-Easy & acc & 0.650 & 0.657 & $-$0.007 \\
HellaSwag & acc\_norm & 0.479 & 0.484 & $-$0.005 \\
PIQA & acc & 0.687 & 0.686 & $+$0.001 \\
WinoGrande & acc & 0.578 & 0.586 & $-$0.008 \\
\bottomrule
\end{tabular}
\caption{Downstream benchmarks (Qwen3-0.6B, $\rho{=}0.4$, seed\,42).
Mixed downstream effects: 4/5 tasks slightly negative (within noise), MMLU $+$1.57pp.}
\label{tab:downstream}
\end{table}

\section{Higher Contamination Details}
\label{app:rho06}

Table~\ref{tab:rho06} reports results at $\rho{=}0.6$.
The full five-method ablation preserves the hierarchy from $\rho{=}0.4$ across all three seeds: Grid ${<}$ Adaptive ${<}$ Uniform ${\approx}$ ESS-only ${<}$ Random.

\begin{table}[h]
\centering
\small
\setlength{\tabcolsep}{3pt}
\begin{tabular}{@{}lcccc@{}}
\toprule
\textbf{Method} & \textbf{Seed 42} & \textbf{Seed 123} & \textbf{Seed 456} & \textbf{Mean} \\
\midrule
Grid ($b{=}0.3$)$^\ddagger$ & \textbf{17.634} & -- & -- & -- \\
Adaptive $\bstar$ & 17.740 & 17.732 & 17.735 & 17.736 $\pm$ .004 \\
Uniform           & 17.766 & 17.754 & 17.770 & 17.763 $\pm$ .008 \\
ESS-only          & 17.770 & 17.760 & 17.760 & 17.763 $\pm$ .006 \\
Random $\mathcal{U}(0,2)$ & 17.832 & 17.870 & 17.880 & 17.861 $\pm$ .025 \\
\bottomrule
\end{tabular}
\caption{Results at $\rho{=}0.6$ (Qwen3-0.6B, $\tau{=}0.8$, $\nmin{=}2$).
$^\ddagger$Post-hoc oracle; seed\,42 only.
Adaptive vs.\ Uniform: $\Delta{=}{-}0.028$, directionally consistent across all seeds.
ESS-only collapses onto Uniform (both $17.763$); Random ($17.861$) confirms detector signal is load-bearing.}
\label{tab:rho06}
\end{table}

The ESS-only/Uniform gap collapses from 0.043 at $\rho{=}0.4$ to 0.000 at $\rho{=}0.6$ (three-seed means: both $17.763$); ESS binding rises to ${\sim}$66\% of batches, leaving insufficient room for $b$ to effectively suppress synthetic samples.
The adaptive method maintains its advantage ($\Delta{=}{-}0.028$, consistent across seeds) through the $\aeff$ quality constraint, which operates independently of the ESS ceiling.
Random reweighting ($17.861 \pm 0.025$) is substantially worse than Uniform, with the highest cross-seed variance, confirming that uninformed weights add noise without corrective signal.
The Adaptive-vs-Grid gap is 0.013 at $\rho{=}0.4$ and 0.106 at $\rho{=}0.6$ (single seed\,42; the $\rho{=}0.6$ grid result is preliminary and may not generalize across seeds).

\section{\texorpdfstring{$\alpha_{\mathrm{eff}}$}{alpha-eff} Proxy Validation}
\label{app:alpha_validation}

Table~\ref{tab:alpha_corr} reports the correlation between $\aeff(0)$ (the detector-based proxy at $b{=}0$) and the true batch-level real fraction $\alpha_{\mathrm{true}}$, computed over all training batches at $\rho{=}0.4$ (seed\,42).

\begin{table}[h]
\centering
\small
\begin{tabular}{@{}ccccc@{}}
\toprule
$B$ & Pearson $r$ & Spearman $r$ & MAE & Bias \\
\midrule
4  & 0.706 & 0.699 & 0.114 & $-$0.029 \\
8  & 0.697 & 0.683 & 0.097 & $-$0.027 \\
16 & 0.707 & 0.691 & 0.075 & $-$0.031 \\
\bottomrule
\end{tabular}
\caption{Correlation between $\aeff(0)$ and true batch-level real fraction across batch sizes ($\rho{=}0.4$, seed\,42).
Pearson $r \approx 0.70$ is stable across batch sizes.
The consistent negative bias (${\approx}{-}0.03$) indicates that $\aeff$ slightly underestimates the true real fraction, biasing the method toward conservative (less aggressive) intervention.
At $B{=}4$, $\aeff$ takes only five discrete values ($\{0, 0.25, 0.5, 0.75, 1\}$), yet rank correlation is preserved.}
\label{tab:alpha_corr}
\end{table}

The $\aeff$ distribution at $B{=}4$ is concentrated: $\aeff{=}0$ (11\%), 0.25 (34\%), 0.5 (36\%), 0.75 (17\%), 1.0 (3\%).
MAE decreases with batch size (0.114 $\to$ 0.075) as expected from averaging, but the rank-order information that drives $\bstar$ selection is already well-captured at $B{=}4$.

\section{Detector Comparison}
\label{app:detector}

Table~\ref{tab:detector} compares three detector families for adaptive reweighting.
The discriminative TF-IDF+LR detector produces the only improvement over uniform; both generative perplexity detectors degrade performance.
GPT-2's AUC (0.91) exceeds the level at which TF-IDF+LR succeeds, ruling out discrimination accuracy as the sole determinant.
Generative detectors assign high $q$-scores to fluent, predictable human text (false positives concentrated among high-quality samples), systematically inflating $\aeff$ for clean batches and deflating it for contaminated ones, which inverts the minimum-intervention logic.

\begin{table}[h]
\centering
\small
\begin{tabular}{@{}llccc@{}}
\toprule
\textbf{Detector} & \textbf{Type} & \textbf{AUC} & \textbf{Adaptive PPL} & $\boldsymbol{\Delta}$ \\
\midrule
TF-IDF+LR & Discriminative & 0.94 & 17.65 & $-$0.04 \\
GPT-2 PPL & Generative & 0.91 & 17.79 & $+$0.10 \\
N-gram PPL & Generative & 0.73 & 17.82 & $+$0.13 \\
\bottomrule
\end{tabular}
\caption{Detector comparison for adaptive reweighting ($\rho{=}0.4$, seed\,42).
Uniform baseline PPL\,=\,17.69.
$\Delta$ = Adaptive $-$ Uniform (negative is better).
Both generative detectors reverse the advantage despite GPT-2's AUC exceeding the level at which TF-IDF+LR succeeds, indicating that signal type (discriminative vs.\ generative) matters more than discrimination accuracy.}
\label{tab:detector}
\end{table}

\section{Detector and Synthetic Data Details}
\label{app:detector_details}

\paragraph{TF-IDF+LR detector.}
TF-IDF features (unigrams + bigrams, max 50{,}000 features, sublinear TF) fed to Logistic Regression (C\,=\,1.0, L2 penalty, solver\,=\,lbfgs, max\_iter\,=\,100).
Trained on a held-out labeled split (10K documents per class).
Post-hoc temperature scaling applied when uncalibrated ECE exceeds 0.05: a scalar $T$ is searched via \texttt{scipy.optimize.minimize\_scalar} over $[0.1, 10.0]$ on a 20\% stratified validation split, yielding $T{=}0.204$ (ECE reduced from 0.12 to 0.048).
The detector is selected automatically from six configurations as the first satisfying AUC $\in [0.85, 0.98]$ and mid-range score ratio $\geq 5\%$.

\paragraph{Synthetic data generation.}
Continuations generated with Qwen3-0.6B (self-generation) using nucleus sampling ($p{=}0.95$, $T{=}0.8$), producing up to 384 tokens per continuation from a 128-token prefix prompt (512 total), targeting ${\sim}$100M synthetic tokens.
Source prompts are the first 128 tokens of randomly sampled FineWeb documents, used as prefix continuations.
Injected at token-level ratio $\rho$ via uniform random mixing across the training corpus.

\section{Low Contamination Analysis}
\label{app:rho02}

At $\rho{=}0.2$, the adaptive method degrades by $+$0.046 PPL relative to uniform (0.26\% relative, seed\,42).
The detector's mean $q$-score at this contamination level is 0.393 (vs.\ 0.487 at $\rho{=}0.4$), indicating that many clean samples receive moderate $q$-scores, blurring the provenance signal.
The regime decomposition reveals 13.7\% clean batches ($\bstar{=}0$), 60.1\% $\aeff$-binding, and 26.3\% ESS-binding, with mean $\bstar{=}1.735$ in reweighted batches.
The high $\aeff$-binding rate (60.1\% vs.\ 38.2\% at $\rho{=}0.4$) means the method actively intervenes rather than defaulting to $\bstar{=}0$, but the unreliable signal causes it to suppress useful training data.
This is consistent with the generative detector failures: when $q$-scores do not reliably separate provenance, the minimum intervention framework amplifies the error rather than correcting it.
The effective range of the method is $\rho \geq 0.4$ with $\tau{=}0.8$; lower $\tau$ values may extend the range but have not been tested at $\rho{=}0.2$.

\section{Cross-Model Transfer}
\label{app:cross_model}

Preliminary single-seed results for Llama-3.2-3B as a cross-generator (synthetic data generated by Llama, training on Qwen3-0.6B) are shown in Table~\ref{tab:cross_model}.
Results are mixed: MMLU improves while HellaSwag slightly degrades, consistent with the pattern observed in Qwen3-1.7B downstream evaluation (\S\ref{sec:robustness}).
Perplexity comparison omitted due to inconsistent evaluation configurations; checkpoints were not retained for re-evaluation.

\begin{table}[h]
\centering
\small
\begin{tabular}{@{}lccc@{}}
\toprule
\textbf{Metric} & \textbf{Uniform} & \textbf{Adaptive} & $\boldsymbol{\Delta}$ \\
\midrule
MMLU (5-shot) & 51.85\% $\pm$ .41 & 53.42\% $\pm$ .41 & $+$1.57pp \\
HellaSwag (10-shot, acc\_norm) & 73.08\% $\pm$ .44 & 72.49\% $\pm$ .45 & $-$0.60pp \\
\bottomrule
\end{tabular}
\caption{Cross-model transfer: Llama-3.2-3B generator, Qwen3-0.6B trainer ($\rho{=}0.4$, single seed).
Mixed results reflect evaluation-set distribution sensitivity rather than consistent quality differences.}
\label{tab:cross_model}
\end{table}

